export interface ConnectorConfig {
  /** Slack bot token with chat:write scope. */
  slackBotToken: string
  /** Injected fetch for testing. */
  fetch?: typeof fetch
}

export interface TwilioSmsPayload {
  Body: string
  From: string
  MessageSid: string
  AccountSid?: string
  To?: string
  [key: string]: unknown
}

export interface HandleResult {
  slackChannelId: string
  slackTimestamp: string
  routedTo: 'sales' | 'support'
}

const SALES_KEYWORDS = /pricing|quote|demo/i
const SLACK_API_URL = 'https://slack.com/api/chat.postMessage'

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function validatePayload(payload: TwilioSmsPayload): void {
  if (!payload.Body || typeof payload.Body !== 'string') {
    throw new Error('Missing required field: Body')
  }
  if (!payload.From || typeof payload.From !== 'string') {
    throw new Error('Missing required field: From')
  }
}

function determineChannel(body: string): 'sales' | 'support' {
  return SALES_KEYWORDS.test(body) ? 'sales' : 'support'
}

export async function handle(
  payload: TwilioSmsPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)

  const channel = determineChannel(payload.Body)
  const fetchImpl = getFetch(config)

  const requestBody = {
    channel,
    text: payload.Body,
  }

  const response = await fetchImpl(SLACK_API_URL, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at ${SLACK_API_URL}`)
  }

  const data = await response.json() as { ok: boolean; channel: string; ts: string }

  if (!data.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(data)}`)
  }

  return {
    slackChannelId: data.channel,
    slackTimestamp: data.ts,
    routedTo: channel,
  }
}

