    const result = await handle(SOURCE_EXAMPLE as unknown as TwilioSmsPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.routedTo).toBe('sales')
    expect(result.slackChannelId).toBe('C01XXXXXXXX')
